from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class ReasoningEffort(str, Enum):
    """Reasoning effort levels accepted by Copilot v2 providers."""

    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"


# Anthropic enforces budget_tokens >= 1024 and budget_tokens < max_tokens.
# We cap our exposed budgets to safely fit under our 16384 max_tokens ceiling.
_DEFAULT_THINKING_BUDGET = 8192


@dataclass(frozen=True)
class ThinkingPref:
    """User preference for reasoning/thinking on a single run.

    ``budget`` is the Anthropic ``budget_tokens`` value.
    ``effort`` is the OpenAI Responses ``reasoning.effort`` value.
    Models that don't support reasoning ignore this entirely.
    """

    enabled: bool = False
    budget: int = _DEFAULT_THINKING_BUDGET
    effort: ReasoningEffort = ReasoningEffort.MEDIUM


@dataclass(frozen=True)
class Message:
    """One chat message passed into the v2 runtime."""

    role: str
    content: str


@dataclass(frozen=True)
class RunRequest:
    """Input payload for one AG-UI / Copilot v2 run."""

    thread_id: str
    run_id: str
    messages: tuple[Message, ...]
    state: dict[str, Any] = field(default_factory=dict)
    model: str | None = None
    thinking: ThinkingPref = field(default_factory=ThinkingPref)
